class Session : Closeable {
    private var closed = false
    private val channel = Files.newByteChannel(Path.of("session.bin"))

    override fun close() {                   // idempotent cascade
        if (!closed) { closed = true; channel.close() }
    }
}
fun handle() = Session().use { it.roundTrip() }   // closed on exit or exception
